import datetime

def add_business_days(start, n, holidays):
    # validate n
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    # parse start
    try:
        cur = datetime.datetime.strptime(start, "%Y-%m-%d").date()
    except Exception:
        raise ValueError("start must be YYYY-MM-DD")
    # parse holidays set
    hol_set = set()
    for h in holidays:
        try:
            d = datetime.datetime.strptime(h, "%Y-%m-%d").date()
        except Exception:
            raise ValueError(f"holiday {h} must be YYYY-MM-DD")
        hol_set.add(d)
    if n == 0:
        return start
    count = 0
    while count < n:
        cur += datetime.timedelta(days=1)
        if cur.weekday() < 5 and cur not in hol_set:
            count += 1
    return cur.strftime("%Y-%m-%d")

