import datetime
import re

def _valid_date_str(s):
    if not isinstance(s, str):
        return False
    if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
        return False
    try:
        datetime.datetime.strptime(s, "%Y-%m-%d")
        return True
    except ValueError:
        return False

